// The corpus behind the library validation golden (plan 16, P16.3). Each case is a document and the policy it is judged
// under. The golden records what validateLibraryDocument said about every case, and for a valid agent the profile it
// resolved to. The zod schemas must reproduce the golden. Do not edit this file to match new code: the golden is
// regenerated from main, deliberately, with regen-validation-golden.ts, as the X1 snapshot is.

import { type AgentProfile, BUILTIN_PROFILES, TIERS } from "../../src/agents/profile.ts";
import type { LibraryKind } from "../../src/library/store.ts";
import { type LibraryPolicy, NO_LIBRARY_POLICY } from "../../src/library/validate.ts";

export interface Case {
  name: string;
  kind: LibraryKind;
  id: string;
  document: unknown;
  policy: "bare" | "full";
}

const FILE_PROVIDER = "file-p";
const FILE_MODEL = "file-model";
const DISABLED_BASE = "file-off";
const POOLED_BASE = "pooled-base";
const BUILTIN = BUILTIN_PROFILES[0]!.id;

/** What the operator's file contributes: an enabled built-in, a built-in the file leaves off, a pooled profile, and one
 *  provider with one model. A library document may extend the enabled ones, and only those. */
export const FULL_POLICY: LibraryPolicy = {
  providerKeyEnv: ["LIB_KEY"],
  bases: [
    { profile: BUILTIN_PROFILES[0]!, enabledByFile: true },
    { profile: { ...BUILTIN_PROFILES[1]!, id: DISABLED_BASE }, enabledByFile: false },
    { profile: { id: POOLED_BASE, argv: ["echo"], parser: "plain", enabled: true, pool: "p1" } as unknown as AgentProfile, enabledByFile: true },
  ],
  providers: { [FILE_PROVIDER]: { protocol: "openai-compatible", baseUrl: "https://files.example/v1/", apiKeyEnv: ["FILE_KEY"], models: [{ id: FILE_MODEL }] } },
  reservedProviderIds: [FILE_PROVIDER],
};

export const POLICIES: Record<Case["policy"], LibraryPolicy> = { bare: NO_LIBRARY_POLICY, full: FULL_POLICY };

/** A valid agent extending a profile, and a valid native agent. Every variant below changes one thing of these. */
const EXTENDING: Record<string, unknown> = {
  extends: BUILTIN, description: "d", tags: ["t"], tier: "standard", timeoutMs: 1000, enabled: true, model: FILE_MODEL, provider: FILE_PROVIDER, temperature: 0.5,
};
const NATIVE: Record<string, unknown> = {
  adapter: "native", role: "writer", nativeRole: "worker", description: "d", tags: ["t"], tier: "cheap", timeoutMs: 1000, enabled: true, model: FILE_MODEL, provider: FILE_PROVIDER, temperature: 0.5,
};

/** Values each agent field must refuse, and values at its edges that it must accept. */
const WRONG: Record<string, unknown[]> = {
  description: [7, null, ["d"]],
  tags: ["x", ["t", 1], null],
  tier: ["bogus", 1],
  timeoutMs: ["1000", 0, -5, 3600001, null],
  enabled: ["yes", 1],
  model: [3, null],
  provider: [["x"], null],
  temperature: ["hot", -0.1, 2.0001, null],
  adapter: ["other", null],
  role: ["boss", null],
  nativeRole: ["builder", null],
  extends: [5, null],
};
const EDGES: Record<string, unknown[]> = {
  timeoutMs: [1, 3600000],
  temperature: [0, 2, 1.5],
  tier: [...TIERS],
  role: ["advisor"],
  nativeRole: ["repair"],
  tags: [[]],
};
const FILE_ONLY = ["argv", "env", "homeOverlay", "permissions", "maxBudgetUsd", "parser", "pool", "steerable", "disabledReason"];

const without = (o: Record<string, unknown>, key: string): Record<string, unknown> => {
  const copy = { ...o };
  delete copy[key];
  return copy;
};

function agentCases(): Case[] {
  const out: Case[] = [];
  const add = (name: string, id: string, document: unknown, policy: Case["policy"] = "full") => out.push({ name, kind: "agents", id, document, policy });
  for (const [label, base, id] of [["extending", EXTENDING, "lib-ext"], ["native", NATIVE, "lib-nat"]] as const) {
    add(`${label}: valid`, id, base);
    for (const key of Object.keys(base)) {
      add(`${label}: ${key} absent`, id, without(base, key));
      add(`${label}: ${key} null`, id, { ...base, [key]: null });
    }
    for (const [key, values] of Object.entries(WRONG)) if (key in base) values.forEach((v) => add(`${label}: ${key} wrong ${JSON.stringify(v)}`, id, { ...base, [key]: v }));
    for (const [key, values] of Object.entries(EDGES)) if (key in base) values.forEach((v) => add(`${label}: ${key} edge ${JSON.stringify(v)}`, id, { ...base, [key]: v }));
    for (const key of FILE_ONLY) add(`${label}: file-only ${key}`, id, { ...base, [key]: "x" });
    add(`${label}: unknown key`, id, { ...base, bogus_key: 1 });
    add(`${label}: id mismatch`, id, { ...base, id: "other" });
  }
  // a field of the other variant
  add("extending: native-only adapter", "lib-ext", { ...EXTENDING, adapter: "native" });
  add("extending: native-only role", "lib-ext", { ...EXTENDING, role: "writer" });
  // the rules that need a valid shape
  add("extending: unknown base", "lib-ext", { ...EXTENDING, extends: "nope" });
  add("extending: pooled base", "lib-ext", { ...EXTENDING, extends: POOLED_BASE });
  add("extending: file-disabled base, enabled true", "lib-ext", { ...EXTENDING, extends: DISABLED_BASE, enabled: true });
  add("extending: file-disabled base, enabled false", "lib-ext", { ...EXTENDING, extends: DISABLED_BASE, enabled: false });
  add("extending: file-disabled base, enabled unset", "lib-ext", without({ ...EXTENDING, extends: DISABLED_BASE }, "enabled"));
  add("extending: id is a built-in", BUILTIN, { ...EXTENDING });
  add("native: id is a built-in", BUILTIN, { ...NATIVE });
  add("native: provider undeclared", "lib-nat", { ...NATIVE, provider: "ghost" });
  add("native: model undeclared", "lib-nat", { ...NATIVE, model: "nope" });
  add("extending: provider undeclared", "lib-ext", { ...EXTENDING, extends: BUILTIN, provider: "ghost" });
  // the gate: a shape problem stops the semantic rules, so only the shape is reported
  add("gate: shape and semantic problems together", "lib-nat", { ...NATIVE, description: 7, provider: "ghost" });
  add("gate: unknown key and undeclared model together", "lib-nat", { ...NATIVE, bogus_key: 1, model: "nope" });
  // not an object
  for (const v of [null, [], 5, "x"]) add(`agents: not an object ${JSON.stringify(v)}`, "lib-nat", v);
  return out;
}

function skillCases(): Case[] {
  const SKILL = { name: "n", description: "d", content: "# skill", tags: ["t"] };
  const out: Case[] = [];
  const add = (name: string, id: string, document: unknown) => out.push({ name, kind: "skills", id, document, policy: "bare" });
  add("valid", "lib-skill", SKILL);
  add("extra key is ignored", "lib-skill", { ...SKILL, extra: 1 });
  add("no tags", "lib-skill", without(SKILL, "tags"));
  add("tags empty", "lib-skill", { ...SKILL, tags: [] });
  add("tags not an array", "lib-skill", { ...SKILL, tags: "x" });
  add("tags with a non-string", "lib-skill", { ...SKILL, tags: ["a", 1] });
  add("name absent", "lib-skill", without(SKILL, "name"));
  add("name blank", "lib-skill", { ...SKILL, name: "  " });
  add("name not a string", "lib-skill", { ...SKILL, name: 5 });
  add("name null", "lib-skill", { ...SKILL, name: null });
  add("description absent", "lib-skill", without(SKILL, "description"));
  add("description not a string", "lib-skill", { ...SKILL, description: 3 });
  add("content absent", "lib-skill", without(SKILL, "content"));
  add("content empty", "lib-skill", { ...SKILL, content: "" });
  add("content blank", "lib-skill", { ...SKILL, content: "   " });
  add("content not a string", "lib-skill", { ...SKILL, content: 5 });
  add("content of exactly 65536 bytes", "lib-skill", { ...SKILL, content: "a".repeat(65536) });
  add("content of 65537 bytes", "lib-skill", { ...SKILL, content: "a".repeat(65537) });
  add("content of 65536 bytes in two-byte characters", "lib-skill", { ...SKILL, content: "é".repeat(32768) });
  add("content of 65538 bytes in two-byte characters", "lib-skill", { ...SKILL, content: "é".repeat(32769) });
  add("id mismatch", "lib-skill", { ...SKILL, id: "other" });
  add("id matches", "lib-skill", { ...SKILL, id: "lib-skill" });
  for (const v of [null, [], 5, "x"]) add(`skills: not an object ${JSON.stringify(v)}`, "lib-skill", v);
  return out;
}

function providerCases(): Case[] {
  const PROVIDER = { protocol: "openai-compatible", baseUrl: "https://p.example/v1/", apiKeyEnv: ["LIB_KEY"], models: [{ id: "m" }] };
  const out: Case[] = [];
  const add = (name: string, id: string, document: unknown, policy: Case["policy"] = "full") => out.push({ name, kind: "providers", id, document, policy });
  add("valid", "lib-p", PROVIDER);
  add("loopback address is allowed", "lib-p", { ...PROVIDER, baseUrl: "http://127.0.0.1:9/v1/" });
  add("metadata address refused (D3)", "lib-p", { ...PROVIDER, baseUrl: "https://169.254.169.254/v1/" });
  add("plain http to a name", "lib-p", { ...PROVIDER, baseUrl: "http://example.com/" });
  add("key name outside the allowlist (IC2)", "lib-p", { ...PROVIDER, apiKeyEnv: ["OTHER_KEY"] });
  add("no key names", "lib-p", { ...PROVIDER, apiKeyEnv: [] });
  add("key name malformed", "lib-p", { ...PROVIDER, apiKeyEnv: ["lower-case"] });
  add("reserved provider id (the file's)", FILE_PROVIDER, { ...PROVIDER });
  add("protocol not supported", "lib-p", { ...PROVIDER, protocol: "anthropic" });
  add("no models", "lib-p", { ...PROVIDER, models: [] });
  add("model without id", "lib-p", { ...PROVIDER, models: [{}] });
  add("model duplicated", "lib-p", { ...PROVIDER, models: [{ id: "m" }, { id: "m" }] });
  add("one price without the other", "lib-p", { ...PROVIDER, models: [{ id: "m", usdPer1MIn: 1 }] });
  add("negative price", "lib-p", { ...PROVIDER, models: [{ id: "m", usdPer1MIn: -1, usdPer1MOut: 2 }] });
  add("both prices declared", "lib-p", { ...PROVIDER, models: [{ id: "m", usdPer1MIn: 1, usdPer1MOut: 2 }] });
  add("id is not a slug", "Bad_ID", { ...PROVIDER });
  add("id mismatch", "lib-p", { ...PROVIDER, id: "other" });
  add("not an object", "lib-p", null);
  return out;
}

function templateCases(): Case[] {
  const out: Case[] = [];
  const add = (name: string, id: string, document: unknown) => out.push({ name, kind: "templates", id, document, policy: "bare" });
  add("empty", "lib-t", {});
  add("any shape", "lib-t", { anything: [1, 2] });
  add("id mismatch", "lib-t", { id: "other" });
  add("not an object", "lib-t", null);
  return out;
}

/** Every case, in a fixed order. The golden is keyed by position, so only append to this list when regenerating. */
export function cases(): Case[] {
  return [...agentCases(), ...skillCases(), ...providerCases(), ...templateCases()];
}
